assertions.code:
$f = $GLOBALS['cli_fixture'];

    foreach ($f['posts'] as $slug=>$id) {
        $expected=$f['before'][$id]; $actual=get_post($id,ARRAY_A);
        $wanted=str_starts_with($slug,'cli-move-') ? $f['users']['cli-new-writer'] : $f['users']['cli-old-writer'];
        if ((int)$actual['post_author']!==$wanted) { return false; }
        foreach (array('post_status','post_content','post_title','post_type') as $key) { if ($actual[$key]!==$expected[$key]) { return false; } }
        if (str_starts_with($slug,'cli-move-') && (get_post_meta($id,'_tracking',true)!=='keep' || wp_get_post_categories($id)!==array($f['terms']['cli-handover']))) { return false; }
    } return true;

$f = $GLOBALS['cli_fixture'];
$allow = array(
    $f['posts']['cli-move-a'] => array( 'fields' => array( 'post_author', 'post_date', 'post_date_gmt', 'post_modified', 'post_modified_gmt' ) ),
    $f['posts']['cli-move-b'] => array( 'fields' => array( 'post_author', 'post_date', 'post_date_gmt', 'post_modified', 'post_modified_gmt' ) ),
);
return $f['content_before']->preserved( $allow );

