$f = $GLOBALS['cli_fixture'];

    foreach ($f['posts'] as $slug=>$id) {
        $p=get_post($id); $before=$f['before'][$id];
        if (in_array($slug,array('cli-future-a','cli-future-b'),true)) {
            if ($p->post_status!=='future' || $p->post_date!=='2037-12-15 09:30:00' || $p->post_date_gmt!=='2037-12-15 14:30:00') { return false; }
        } elseif ($p->post_date!==$before['post_date'] || $p->post_date_gmt!==$before['post_date_gmt'] || $p->post_status!==$before['post_status']) { return false; }
    } return true;

